sources":{"contracts/SessionFactory.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {ISeerMarketFactory} from "./interfaces/ISeerMarketFactory.sol";

/// @title SessionFactory
/// @notice Permissionless orchestrator around Seer's `MarketFactory`: one categorical or
///         multi-categorical parent and one scalar child per parent outcome.
/// @dev Trusts the Seer `MarketFactory` at `seerMarketFactory` for market clones, Reality
///      metadata, and CTF wiring.
contract SessionFactory {
  // ************************************* //
  // *         Enums / Structs           * //
  // ************************************* //

  /// @notice On-chain record for a session.
  /// @dev For phased deploys, `completedAt` is 0 until all children exist.
  struct Session {
    address deployer;
    address parentMarket;
    address[] childMarkets;
    uint64 openedAt;
    uint64 completedAt;
    uint256 expectedChildCount;
  }

  /// @notice Parent categorical market configuration passed to Seer.
  struct ParentCategoricalConfig {
    string marketName;
    string[] outcomes;
    string[] tokenNames;
    string category;
    string lang;
    uint256 minBond;
    uint32 openingTime;
  }

  /// @notice Scalar child market configuration for one parent outcome branch.
  struct ChildScalarConfig {
    uint256 parentOutcomeIndex;
    string marketName;
    string outcomeLabelLow;
    string outcomeLabelHigh;
    string tokenNameLow;
    string tokenNameHigh;
    uint256 lowerBound;
    uint256 upperBound;
    uint256 minBond;
    uint32 openingTime;
    string category;
    string lang;
  }

  /// @notice Atomic or phased session deploy input.
  struct DeploySessionParams {
    ParentCategoricalConfig parent;
    ChildScalarConfig[] children;
    bool multiCategoricalParent;
  }

  // ************************************* //
  // *             Storage               * //
  // ************************************* //

  /// @dev Seer scalar markets expose two branch outcomes (low / high).
  uint256 private constant SCALAR_BRANCH_OUTCOME_COUNT = 2;

  /// @dev Seer wrapped scalar tokens use three name slots (low, high, unused).
  uint256 private constant SEER_WRAPPED_TOKEN_NAME_SLOTS = 3;

  /// @dev Seer reserves headroom below `type(uint256).max` for scalar branch encoding.
  uint256 private constant SCALAR_UPPER_BOUND_HEADROOM = 2;

  /// @dev Largest inclusive `upperBound` accepted by `_validateScalarBounds`.
  uint256 private constant SCALAR_MAX_VALID_UPPER_BOUND = type(uint256).max - SCALAR_UPPER_BOUND_HEADROOM;

  /// @dev Parent markets have no parent outcome index in Seer.
  uint256 private constant NO_PARENT_OUTCOME = 0;

  /// @dev Parent markets are not linked to an existing parent market in Seer.
  address private constant NO_PARENT_MARKET = address(0);

  /// @dev Seer accepts empty Reality metadata at this orchestration layer by design.
  string private constant OMITTED_REALITY_METADATA = "";

  /// @dev Third Seer wrapped token name slot is unused for scalar children.
  string private constant EMPTY_WRAPPED_TOKEN_NAME = "";

  /// @notice Seer market factory used for parent and scalar clones.
  /// @dev Immutable reference; trust is deployment-time configuration. TRUSTED.
  ISeerMarketFactory public immutable seerMarketFactory;

  /// @notice Monotonic session id allocator; also the count of sessions ever opened.
  uint256 public sessionCount;

  /// @notice Stored session records keyed by session id.
  mapping(uint256 sessionId => Session session) public sessions;

  // ************************************* //
  // *              Events               * //
  // ************************************* //

  /// @notice Emitted when a parent market clone is created for a session.
  event ParentMarketDeployed(
    uint256 indexed sessionId,
    address indexed deployer,
    address indexed parentMarket,
    uint256 outcomeCount
  );

  /// @notice Emitted when a scalar child market clone is created for a session.
  event ChildMarketDeployed(
    uint256 indexed sessionId,
    uint256 indexed parentOutcomeIndex,
    address indexed childMarket,
    address parentMarket
  );

  /// @notice Restricts phased child batches to the original session deployer.
  /// @param sessionId Session being updated.
  modifier onlySessionDeployer(uint256 sessionId) {
    if (sessionId >= sessionCount) revert InvalidSession();
    if (msg.sender != sessions[sessionId].deployer) revert NotSessionDeployer();
    _;
  }

  // ************************************* //
  // *            Constructor            * //
  // ************************************* //

  /// @notice Binds this factory to a Seer `MarketFactory` deployment.
  /// @param factory Seer market factory used for all market clones.
  /// @dev The factory implementation is TRUSTED.
  constructor(ISeerMarketFactory factory) {
    seerMarketFactory = factory;
  }

  // ************************************* //
  // *         State Modifiers           * //
  // ************************************* //

  /// @notice Atomic deploy: parent + all scalar children in one transaction.
  /// @param params Validated parent and child configuration.
  /// @return sessionId Allocated session id.
  /// @return parentAddress Seer parent market clone.
  /// @return childMarkets Seer scalar child clones in parent outcome order.
  /// @dev O(n) in the number of parent outcomes; each outcome triggers one Seer clone. TRUSTED.
  function deploySession(
    DeploySessionParams calldata params
  ) external returns (uint256 sessionId, address parentAddress, address[] memory childMarkets) {
    _validateParentAndChildren(params.parent, params.children);
    uint256 parentOutcomeCount = params.parent.outcomes.length;

    sessionId = sessionCount;
    address deployer = msg.sender;
    sessionCount = sessionId + 1;

    parentAddress = _seerCreateParent(params.parent, params.multiCategoricalParent);

    emit ParentMarketDeployed(sessionId, deployer, parentAddress, parentOutcomeCount);

    childMarkets = new address[](parentOutcomeCount);
    for (uint256 parentOutcomeIndex = 0; parentOutcomeIndex < parentOutcomeCount; parentOutcomeIndex++) {
      childMarkets[parentOutcomeIndex] = _deployChildScalarForSession(
        params.children[parentOutcomeIndex],
        parentAddress,
        sessionId,
        parentOutcomeIndex
      );
    }

    uint64 timestamp = uint64(block.timestamp);
    sessions[sessionId] = Session({
      deployer: deployer,
      parentMarket: parentAddress,
      childMarkets: childMarkets,
      openedAt: timestamp,
      completedAt: timestamp,
      expectedChildCount: parentOutcomeCount
    });
  }

  /// @notice Phased step 1: deploy parent only; full child config is validated and published.
  /// @param params Validated parent and child configuration.
  /// @return sessionId Allocated session id.
  /// @return parentAddress Seer parent market clone.
  /// @dev O(n) in the number of parent outcomes for validation and config publication. TRUSTED.
  function openPhasedSession(
    DeploySessionParams calldata params
  ) external returns (uint256 sessionId, address parentAddress) {
    _validateParentAndChildren(params.parent, params.children);

    sessionId = sessionCount;
    address deployer = msg.sender;
    sessionCount = sessionId + 1;

    parentAddress = _seerCreateParent(params.parent, params.multiCategoricalParent);

    uint256 outcomeCount = params.parent.outcomes.length;

    emit ParentMarketDeployed(sessionId, deployer, parentAddress, outcomeCount);
    emit PhasedSessionChildConfigPublished(sessionId, params.children);

    sessions[sessionId] = Session({
      deployer: deployer,
      parentMarket: parentAddress,
      childMarkets: new address[](0),
      openedAt: uint64(block.timestamp),
      completedAt: 0,
      expectedChildCount: outcomeCount
    });
  }

  /// @notice Phased step 2+: append scalar children in strict index order.
  /// @param sessionId Session opened via `openPhasedSession`.
  /// @param childBatch One or more child configs; indices must continue the stored sequence.
  /// @dev O(m) in batch size `m`; each entry triggers one Seer clone. TRUSTED.
  function deploySessionChildBatch(
    uint256 sessionId,
    ChildScalarConfig[] calldata childBatch
  ) external onlySessionDeployer(sessionId) {
    Session storage session = sessions[sessionId];
    if (session.completedAt != 0) revert SessionAlreadyComplete();

    uint256 start = session.childMarkets.length;
    uint256 batchSize = childBatch.length;

    if (batchSize == 0) revert InvalidConfig();
    if (start + batchSize > session.expectedChildCount) revert ChildBatchExceedsExpected();

    _validateChildBatch(childBatch, start);

    address parent = session.parentMarket;
    for (uint256 i = 0; i < batchSize; i++) {
      uint256 globalIndex = start + i;
      address childAddress = _deployChildScalarForSession(childBatch[i], parent, sessionId, globalIndex);
      session.childMarkets.push(childAddress);
    }

    if (session.childMarkets.length == session.expectedChildCount) {
      session.completedAt = uint64(block.timestamp);
    }
  }

  // ************************************* //
  // *           Public Views            * //
  // ************************************* //

  /// @notice Returns the stored session struct.
  /// @param sessionId Session id to load.
  /// @return session Stored session record.
  /// @dev O(1); reverts for unknown ids.
  function getSession(uint256 sessionId) external view returns (Session memory session) {
    if (sessionId >= sessionCount) revert InvalidSession();
    session = sessions[sessionId];
  }

  // ************************************* //
  // *            Internal               * //
  // ************************************* //

  /// @notice Validates parent outcome cardinality and child ordering/bounds.
  /// @param parentConfig Parent market configuration.
  /// @param childConfigs Scalar child configuration, one per parent outcome.
  /// @dev O(n) in the number of parent outcomes.
  function _validateParentAndChildren(
    ParentCategoricalConfig calldata parentConfig,
    ChildScalarConfig[] calldata childConfigs
  ) private pure {
    uint256 parentOutcomeCount = parentConfig.outcomes.length;
    if (childConfigs.length != parentOutcomeCount || parentConfig.tokenNames.length != parentOutcomeCount + 1) {
      revert InvalidConfig();
    }

    for (uint256 parentOutcomeIndex = 0; parentOutcomeIndex < parentOutcomeCount; parentOutcomeIndex++) {
      if (childConfigs[parentOutcomeIndex].parentOutcomeIndex != parentOutcomeIndex) {
        revert InvalidConfig();
      }
      _validateScalarBounds(childConfigs[parentOutcomeIndex].lowerBound, childConfigs[parentOutcomeIndex].upperBound);
    }
  }

  /// @notice Validates phased child batch indices and scalar bounds before Seer calls.
  /// @param childBatch Child configs to deploy in this transaction.
  /// @param start Next expected parent outcome index.
  /// @dev O(m) in batch size `m`.
  function _validateChildBatch(ChildScalarConfig[] calldata childBatch, uint256 start) private pure {
    uint256 batchSize = childBatch.length;
    for (uint256 i = 0; i < batchSize; i++) {
      uint256 globalIndex = start + i;
      ChildScalarConfig calldata childConfig = childBatch[i];
      if (childConfig.parentOutcomeIndex != globalIndex) revert InvalidConfig();
      _validateScalarBounds(childConfig.lowerBound, childConfig.upperBound);
    }
  }

  /// @notice Ensures scalar bounds are non-degenerate and within Seer's accepted range.
  /// @param lowerBound Scalar lower bound.
  /// @param upperBound Scalar upper bound.
  /// @dev O(1).
  function _validateScalarBounds(uint256 lowerBound, uint256 upperBound) private pure {
    if (lowerBound >= upperBound || upperBound > SCALAR_MAX_VALID_UPPER_BOUND) {
      revert InvalidConfig();
    }
  }

  /// @notice Creates a categorical or multi-categorical parent market via Seer.
  /// @param parentConfig Parent market configuration.
  /// @param multiCategoricalParent When true, uses Seer's multi-categorical factory path.
  /// @return parentAddress Seer parent market clone.
  /// @dev O(1) per call. `questionStart`, `questionEnd`, and `outcomeType` are omitted by design. TRUSTED.
  function _seerCreateParent(
    ParentCategoricalConfig calldata parentConfig,
    bool multiCategoricalParent
  ) private returns (address parentAddress) {
    ISeerMarketFactory.CreateMarketParams memory createParams = ISeerMarketFactory.CreateMarketParams({
      marketName: parentConfig.marketName,
      outcomes: parentConfig.outcomes,
      questionStart: OMITTED_REALITY_METADATA,
      questionEnd: OMITTED_REALITY_METADATA,
      outcomeType: OMITTED_REALITY_METADATA,
      parentOutcome: NO_PARENT_OUTCOME,
      parentMarket: NO_PARENT_MARKET,
      category: parentConfig.category,
      lang: parentConfig.lang,
      lowerBound: NO_PARENT_OUTCOME,
      upperBound: NO_PARENT_OUTCOME,
      minBond: parentConfig.minBond,
      openingTime: parentConfig.openingTime,
      tokenNames: parentConfig.tokenNames
    });

    parentAddress = multiCategoricalParent
      ? seerMarketFactory.createMultiCategoricalMarket(createParams)
      : seerMarketFactory.createCategoricalMarket(createParams);
  }

  /// @notice Creates one scalar child market linked to a parent outcome branch.
  /// @param childConfig Scalar child configuration.
  /// @param parentAddress Parent market clone address.
  /// @param sessionId Session being populated.
  /// @param parentOutcomeIndex Parent outcome branch index.
  /// @return childAddress Seer scalar child clone.
  /// @dev O(1) per call. `questionStart`, `questionEnd`, and `outcomeType` are omitted by design. TRUSTED.
  function _deployChildScalarForSession(
    ChildScalarConfig calldata childConfig,
    address parentAddress,
    uint256 sessionId,
    uint256 parentOutcomeIndex
  ) private returns (address childAddress) {
    string[] memory outcomeLabels = _buildScalarOutcomeLabels(childConfig);
    string[] memory wrappedTokenNames = _buildScalarWrappedTokenNames(childConfig);

    ISeerMarketFactory.CreateMarketParams memory createParams = ISeerMarketFactory.CreateMarketParams({
      marketName: childConfig.marketName,
      outcomes: outcomeLabels,
      questionStart: OMITTED_REALITY_METADATA,
      questionEnd: OMITTED_REALITY_METADATA,
      outcomeType: OMITTED_REALITY_METADATA,
      parentOutcome: childConfig.parentOutcomeIndex,
      parentMarket: parentAddress,
      category: childConfig.category,
      lang: childConfig.lang,
      lowerBound: childConfig.lowerBound,
      upperBound: childConfig.upperBound,
      minBond: childConfig.minBond,
      openingTime: childConfig.openingTime,
      tokenNames: wrappedTokenNames
    });

    childAddress = seerMarketFactory.createScalarMarket(createParams);

    emit ChildMarketDeployed({
      sessionId: sessionId,
      parentOutcomeIndex: parentOutcomeIndex,
      childMarket: childAddress,
      parentMarket: parentAddress
    });
  }

  /// @notice Builds the two scalar branch outcome labels expected by Seer.
  /// @param childConfig Scalar child configuration.
  /// @return outcomeLabels Low and high branch labels.
  /// @dev O(1).
  function _buildScalarOutcomeLabels(
    ChildScalarConfig calldata childConfig
  ) private pure returns (string[] memory outcomeLabels) {
    outcomeLabels = new string[](SCALAR_BRANCH_OUTCOME_COUNT);
    outcomeLabels[0] = childConfig.outcomeLabelLow;
    outcomeLabels[1] = childConfig.outcomeLabelHigh;
  }

  /// @notice Builds Seer's three-slot wrapped token name array for scalar markets.
  /// @param childConfig Scalar child configuration.
  /// @return wrappedTokenNames Low, high, and unused third slot.
  /// @dev O(1).
  function _buildScalarWrappedTokenNames(
    ChildScalarConfig calldata childConfig
  ) private pure returns (string[] memory wrappedTokenNames) {
    wrappedTokenNames = new string[](SEER_WRAPPED_TOKEN_NAME_SLOTS);
    wrappedTokenNames[0] = childConfig.tokenNameLow;
    wrappedTokenNames[1] = childConfig.tokenNameHigh;
    wrappedTokenNames[2] = EMPTY_WRAPPED_TOKEN_NAME;
  }

  // ************************************* //
  // *              Errors               * //
  // ************************************* //

  /// @notice Emitted when phased deploy publishes the full validated child configuration.
  event PhasedSessionChildConfigPublished(uint256 indexed sessionId, ChildScalarConfig[] children);

  /// @notice Thrown when deploy parameters fail structural or scalar bound checks.
  error InvalidConfig();

  /// @notice Thrown when a phased child batch is sent by an address other than the deployer.
  error NotSessionDeployer();

  /// @notice Thrown when a session id is unknown or not yet allocated.
  error InvalidSession();

  /// @notice Thrown when phased child batches are sent after the session is complete.
  error SessionAlreadyComplete();

  /// @notice Thrown when a phased child batch would exceed the expected child count.
  error ChildBatchExceedsExpected();
}
